                expect(description.value).toContain('{{Created_1.current}}') // trigger whole object
                expect(description.value).toContain('{{22222222-3333-4444-5555-666666666666.result}}') // action
                expect(description.value).toContain('{{33333333-4444-5555-6666-777777777777.processedResult}}') // subflow
