// Helper to extract inputs from flow logic values (wrapped in FlowLogicValues structure)
function getFlowLogicInputs(valuesBase64: string): any[] {
    const parsed = unzipInputArray(valuesBase64)
    // Flow logic values are wrapped in { inputs: [...] } structure
    return Array.isArray(parsed) ? parsed : ((parsed as any).inputs ?? [])
}

describe('Flow Logic Datapills test suite Fluent -> XML', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())

    describe('If/ElseIf/Else datapill transformation', () => {
        test.skip('If condition with trigger datapill', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-logic-datapills.now.ts', 'datapills')

            // Find the If flow logic instance with trigger datapill condition
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances).toBeDefined()
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Collect all conditions and verify trigger datapills exist
            const allConditions: string[] = []
            for (const instance of flowLogicInstances) {
                if (instance.values) {
                    const inputs = getFlowLogicInputs(instance.values)
                    const condition = findInput(inputs, 'condition')
                    if (condition?.value) {
                        allConditions.push(condition.value)
                    }
                }
            }

            // Verify at least one condition contains trigger datapill format
            const hasTriggerPill = allConditions.some((c) => c.includes('{{Created_1.') || c.includes('priority'))
            expect(hasTriggerPill).toBe(true)
        })

        test.skip('ElseIf condition with action output datapill', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-logic-datapills.now.ts', 'datapills')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find the ElseIf with action output status condition
            const elseIfInstance = flowLogicInstances.find((instance: any) => {
                if (!instance.ui_id || !instance.values) {
                    return false
                }
                const inputs = getFlowLogicInputs(instance.values)
                return inputs.some(
                    (input: any) =>
                        input.name === 'condition' && input.value?.includes('aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee')
                )
            })
            expect(elseIfInstance).toBeDefined()

            const elseIfInputs = getFlowLogicInputs(elseIfInstance.values)
            const condition = findInput(elseIfInputs, 'condition')
            expect(condition.value).toEqual("{{aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee.status}}=='In Progress'")
        })

        test.skip('ElseIf condition with flow variable datapill', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-logic-datapills.now.ts', 'datapills')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find the ElseIf with flow variable condition
            const elseIfInstance = flowLogicInstances.find((instance: any) => {
                if (!instance.ui_id || !instance.values) {
                    return false
                }
                const inputs = getFlowLogicInputs(instance.values)
                return inputs.some(
                    (input: any) =>
                        input.name === 'condition' && input.value?.includes('{{flow_variable.statusFilter}}')
                )
            })
            expect(elseIfInstance).toBeDefined()

            const elseIfInputs = getFlowLogicInputs(elseIfInstance.values)
            const condition = findInput(elseIfInputs, 'condition')
            expect(condition.value).toEqual("{{flow_variable.statusFilter}}=='Pending'")
        })

        test.skip('ElseIf condition with multiple datapills in template', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-logic-datapills.now.ts', 'datapills')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Collect all conditions
            const allConditions: string[] = []
            for (const instance of flowLogicInstances) {
                if (instance.values) {
                    const inputs = getFlowLogicInputs(instance.values)
                    const condition = findInput(inputs, 'condition')
                    if (condition?.value) {
                        allConditions.push(condition.value)
                    }
                }
            }

            // Verify at least one condition contains flow_variable datapill
            const hasFlowVarPill = allConditions.some((c) => c.includes('{{flow_variable.'))
            expect(hasFlowVarPill).toBe(true)

            // Verify we have multiple types of datapills across conditions
            const hasTriggerPill = allConditions.some((c) => c.includes('{{Created_1.'))
            const hasUuidPill = allConditions.some((c) => /\{\{[a-f0-9-]+\./i.test(c))
            expect(hasTriggerPill || hasUuidPill).toBe(true)
        })

        test.skip('Else block has no condition but is processed', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-logic-datapills.now.ts', 'datapills')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances).toBeDefined()

            // Else blocks should exist - they don't have conditions but should be created
            // The Else logic_definition sys_id is different from If/ElseIf
            expect(flowLogicInstances.length).toBeGreaterThan(0)
        })
    })

    describe('Nested flow logic datapill transformation', () => {
        test.skip('Nested flow logic instances have parent relationships', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-logic-datapills.now.ts', 'datapills')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances).toBeDefined()
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Verify some instances have parent_ui_id (indicating nesting)
            const nestedInstances = flowLogicInstances.filter((instance: any) => instance.parent_ui_id)
            expect(nestedInstances.length).toBeGreaterThan(0)

            // Verify we have action output datapills in conditions ({{uuid.*}})
            const allConditions: string[] = []
            for (const instance of flowLogicInstances) {
                if (instance.values) {
                    const inputs = getFlowLogicInputs(instance.values)
                    const condition = findInput(inputs, 'condition')
                    if (condition?.value) {
                        allConditions.push(condition.value)
                    }
                }
            }

            const hasUuidPill = allConditions.some((c) => /\{\{[a-f0-9-]+\./i.test(c))
            expect(hasUuidPill).toBe(true)
        })

        test.skip('Inner ElseIf with flow variable datapill', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-logic-datapills.now.ts', 'datapills')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find inner ElseIf with flow variable level condition (nested)
            const innerElseIfInstance = flowLogicInstances.find((instance: any) => {
                if (!instance.ui_id || !instance.parent_ui_id || !instance.values) {
                    return false
                }
                const inputs = getFlowLogicInputs(instance.values)
                return inputs.some(
                    (input: any) => input.name === 'condition' && input.value?.includes('{{flow_variable.level}}')
                )
            })
            expect(innerElseIfInstance).toBeDefined()

            const innerElseIfInputs = getFlowLogicInputs(innerElseIfInstance.values)
            const condition = findInput(innerElseIfInputs, 'condition')
            expect(condition.value).toEqual("{{flow_variable.level}}=='High'")
        })
    })

    describe('Datapill types in flow logic conditions', () => {
        test.skip('All datapill types are correctly transformed', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-logic-datapills.now.ts', 'datapills')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const allConditions: string[] = []

            // Collect all conditions from flow logic instances
            for (const instance of flowLogicInstances) {
                if (instance.values) {
                    const inputs = getFlowLogicInputs(instance.values)
                    const condition = findInput(inputs, 'condition')
                    if (condition?.value) {
                        allConditions.push(condition.value)
                    }
                }
            }

            // Verify trigger datapills ({{Created_1.*}})
            expect(allConditions.some((c) => c.includes('{{Created_1.'))).toBe(true)

            // Verify action output datapills ({{uuid.*}})
            expect(allConditions.some((c) => /\{\{[a-f0-9-]+\.[a-z]+\}\}/i.test(c))).toBe(true)

            // Verify flow variable datapills ({{flow_variable.*}})
            expect(allConditions.some((c) => c.includes('{{flow_variable.'))).toBe(true)
        })
    })
})

