    describe('Nested forEach datapills', () => {
        test('Nested forEach loops with different parameter names resolve correctly', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'nested-foreach-datapills.now.ts',
                'datapills'
            )

            // Get forEach instances
            const forEachInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(forEachInstances).toBeDefined()
            expect(forEachInstances.length).toBeGreaterThanOrEqual(2)

            // Find outer forEach (departments) and inner forEach (categories)
            // The outer forEach will have the inner forEach as a child (parent_ui_id relationship)
            const outerForEach = forEachInstances.find((instance: any) => instance.ui_id && !instance.parent_ui_id)
            const innerForEach = forEachInstances.find(
                (instance: any) => instance.ui_id && instance.parent_ui_id === outerForEach?.ui_id
            )

            expect(outerForEach).toBeDefined()
            expect(innerForEach).toBeDefined()

            const outerUUID = outerForEach.ui_id
            const innerUUID = innerForEach.ui_id

            // Get all action instances (they should be children of forEach instances)
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances).toBeDefined()
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find actions by their parent_ui_id relationship
            // Actions inside outer forEach (but not in inner forEach)
            const outerActions = actionInstances.filter((a: any) => a.parent_ui_id === outerUUID)

            // Actions inside inner forEach
            const innerActions = actionInstances.filter((a: any) => a.parent_ui_id === innerUUID)

            // Verify we have the expected number of actions
            expect(outerActions.length).toBeGreaterThan(0)
            expect(innerActions.length).toBeGreaterThan(0)

            // Test outer forEach actions - should contain outer UUID with .item
            for (const action of outerActions) {
                const actionInputs = unzipInputArray(action.values)
                const logMessage = findInput(actionInputs, 'log_message')
                if (logMessage?.value.includes('{{')) {
                    // Should contain outer forEach UUID with .item
                    expect(logMessage.value).toMatch(new RegExp(`\\{\\{${outerUUID}\\.item\\.`))
                    // Should NOT contain inner forEach UUID
                    expect(logMessage.value).not.toContain(`{{${innerUUID}`)
                }
            }

            // Test inner forEach actions - should contain both UUIDs with .item
            for (const action of innerActions) {
                const actionInputs = unzipInputArray(action.values)
                const logMessage = findInput(actionInputs, 'log_message')
                if (logMessage?.value.includes('Dept:')) {
                    // This action uses both dept and category
                    // Should contain outer forEach UUID for dept
                    expect(logMessage.value).toMatch(new RegExp(`\\{\\{${outerUUID}\\.item\\.`))
                    // Should contain inner forEach UUID for category
                    expect(logMessage.value).toMatch(new RegExp(`\\{\\{${innerUUID}\\.item\\.`))
                } else if (logMessage?.value.includes('Category:')) {
                    // This action uses only category
                    // Should contain inner forEach UUID
                    expect(logMessage.value).toMatch(new RegExp(`\\{\\{${innerUUID}\\.item\\.`))
                    // Should NOT contain outer forEach UUID
                    expect(logMessage.value).not.toContain(`{{${outerUUID}`)
                }
            }
        })

        describe('Action Instance Data Pills in If Loops', () => {
            test('XML->TypeScript: UUID data pills correctly transform to variable access', async () => {
                const project = ctx.createProject()

                // Load and transform the deployed XML
                const xmlContent = loadTestFile('sys_hub_flow_2836dcae236c428f8095bfe95f0073b9.xml', 'datapills/xmls')
                const { changedFiles } = await project.transform({
                    path: 'sys_hub_flow_2836dcae236c428f8095bfe95f0073b9.xml',
                    content: xmlContent,
                })

                expect(changedFiles).toHaveLength(1)
                const file = changedFiles[0]
                expect(file).toBeDefined()

                const content = file.getContent()

                // Verify UUID format is NOT in generated TypeScript
                expect(content).not.toContain('{{aaa11111-bbbb-cccc-dddd-111111111111.Record}}')
                expect(content).not.toContain('{{ddd44444-eeee-ffff-0000-444444444444.Record}}')

                // Verify UUID data pills are properly converted to TypeScript variable access
                // XML: {{aaa11111-bbbb-cccc-dddd-111111111111.Record}} -> TS: actionInstance_1.Record
                // XML: {{ddd44444-eeee-ffff-0000-444444444444.Record}} -> TS: actionInstance_3.Record
                expect(content).toContain('actionInstance_1.Record')
                expect(content).toContain('actionInstance_3.Record')

                // Verify action definitions and instances are present
                expect(content).toContain('action.core.createTask')
                expect(content).toContain('const actionInstance_1')
                expect(content).toContain('const actionInstance_3')

                // Verify nested if block structure
                expect(content).toContain('wfa.flowLogic.if')

                // Verify condition uses trigger data pill (not UUID)
                expect(content).toMatch(/params\.trigger\.current\.state/)
            })
        })
    })

    describe('Flow Logic Condition Datapill Transform (DEF0782780)', () => {
        test('Transforms XML with updated datapill (table_name) to Fluent code correctly', async () => {
            const project = ctx.createProject()

            // Add the initial source file with the original datapill (current.user_name)
            const sourceContent = loadTestFile('flow-logic-condition-datapill.now.ts', 'create')
            project.addFile({
                path: 'src/fluent/flow-logic-condition-datapill.now.ts',
                content: sourceContent,
            })

            // Load and transform the XML from instance (which has table_name in condition)
            const xmlContent = loadTestFile('sys_hub_flow_3ce1a1c5d4874c8dad6ef03f7b50a85f.xml', 'create')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_3ce1a1c5d4874c8dad6ef03f7b50a85f.xml',
                content: xmlContent,
            })

            // Verify files were transformed
            expect(changedFiles).toHaveLength(1)
            const file = changedFiles[0]
            expect(file).toBeDefined()

            const content = file.getContent()

            expect(content).toContain('params.trigger.table_name')

            // Verify the flow logic if condition uses the updated datapill
            expect(content).toMatch(/condition:\s*`\$\{wfa\.dataPill\(params\.trigger\.table_name/)

            // The log_message should still have current.user_name (unchanged in XML)
            expect(content).toContain('params.trigger.current.user_name')
        })
    })
